/**
 * Reading helpers for the item-image variants generated by
 * `lib/image-pipeline.ts`. Frontend consumers use these to pick the
 * right URL for a given surface (list card, detail hero, etc.) with
 * graceful fallback to legacy fields (cover_url, poster_url, etc.).
 */

import { safeImageUrl } from "@/lib/image-url";
import { extractGalleryImages } from "@/lib/images/gallery";

export type ImageSlot = "poster" | "backdrop";
export type ImageVariant = "s" | "m" | "l" | "xl";

interface SlotVariants {
  s?: string;
  m?: string;
  l?: string;
  xl?: string;
}

export interface ItemImagesShape {
  poster?:   SlotVariants;
  backdrop?: SlotVariants;
  og?:       string;
}

interface ItemLikeForImages {
  images?:       ItemImagesShape | null | unknown;
  poster_url?:   string | null;
  backdrop_url?: string | null;
  cover_url?:    string | null;
}

const VARIANT_FALLBACK: Record<ImageVariant, ImageVariant[]> = {
  s:  ["s",  "m",  "l",  "xl"],
  m:  ["m",  "s",  "l",  "xl"],
  l:  ["l",  "m",  "xl", "s"],
  xl: ["xl", "l",  "m",  "s"],
};

/**
 * Pick a URL for the given slot + preferred variant, falling back through
 * the variant ladder, then to the legacy column for that slot, then to
 * cover_url, then null.
 *
 * Example:
 *   itemImageUrl(item, "poster", "l")
 *     → tries images.poster.l, .m, .xl, .s
 *     → then poster_url
 *     → then cover_url
 *     → null if all empty
 */
export function itemImageUrl(
  item: ItemLikeForImages | null | undefined,
  slot: ImageSlot,
  preferredVariant: ImageVariant,
): string | null {
  if (!item) return null;

  const images = (item.images && typeof item.images === "object" && !Array.isArray(item.images))
    ? (item.images as ItemImagesShape)
    : null;
  const slotData = images?.[slot];

  if (slotData) {
    for (const v of VARIANT_FALLBACK[preferredVariant]) {
      const url = slotData[v];
      if (url) return safeImageUrl(url) ?? url;
    }
  }

  // Legacy column fallback
  if (slot === "poster" && item.poster_url) return safeImageUrl(item.poster_url);
  if (slot === "backdrop" && item.backdrop_url) return safeImageUrl(item.backdrop_url);
  if (item.cover_url) return safeImageUrl(item.cover_url);

  return null;
}

/**
 * Build a srcset string for Next.js <Image> from all available variants.
 * Returns undefined if no variants exist (caller should skip srcset prop).
 *
 * Example output:
 *   "https://.../poster-m.webp 480w, https://.../poster-l.webp 800w, https://.../poster-xl.webp 1600w"
 */
export function itemImageSrcSet(
  item: ItemLikeForImages | null | undefined,
  slot: ImageSlot,
): string | undefined {
  if (!item) return undefined;
  const images = (item.images && typeof item.images === "object" && !Array.isArray(item.images))
    ? (item.images as ItemImagesShape)
    : null;
  const slotData = images?.[slot];
  if (!slotData) return undefined;

  const widthPerVariant: Record<ImageVariant, Record<ImageSlot, number>> = {
    s:  { poster: 200,  backdrop: 320  },
    m:  { poster: 480,  backdrop: 640  },
    l:  { poster: 800,  backdrop: 1280 },
    xl: { poster: 1600, backdrop: 2048 },
  };

  const parts: string[] = [];
  for (const v of ["s", "m", "l", "xl"] as ImageVariant[]) {
    if (slotData[v]) parts.push(`${slotData[v]} ${widthPerVariant[v][slot]}w`);
  }
  return parts.length ? parts.join(", ") : undefined;
}

/** Return the OG / share image URL for an item, or null. */
export function itemOgUrl(item: ItemLikeForImages | null | undefined): string | null {
  if (!item) return null;
  const images = (item.images && typeof item.images === "object" && !Array.isArray(item.images))
    ? (item.images as ItemImagesShape)
    : null;
  if (images?.og) return safeImageUrl(images.og) ?? images.og;
  // Fall back to backdrop_url since OG is landscape-shaped
  if (item.backdrop_url) return safeImageUrl(item.backdrop_url);
  if (item.cover_url) return safeImageUrl(item.cover_url);
  return null;
}

// ── "main" image (store whole, crop on display) ────────────────────────────

export interface MainImageSource {
  /** Default src — the ≤640w variant (or smallest available). */
  src: string;
  /** "url 320w, url 640w, …" for <img srcSet>. */
  srcSet?: string;
  /** CSS object-position for the focal point, e.g. "64% 58%". */
  objectPosition: string;
  /** width / height of the uncropped image, when known. */
  aspect?: number;
}

/**
 * Resolve the uncropped "main" image written by storeMainImage(). Falls
 * back to a plain URL (cover_url / legacy column) so items that have not
 * been migrated still render — centred, without srcset.
 */
export function mainImageSource(
  images: unknown,
  fallbackUrl?: string | null,
): MainImageSource | null {
  // An admin-picked gallery cover (gallery[].isDefault) wins over the
  // automatic main image, same precedence as pickCoverUrl().
  const adminCover = extractGalleryImages(images).find((g) => g.isDefault)?.url;
  if (adminCover) {
    const url = safeImageUrl(adminCover);
    if (url) return { src: url, objectPosition: "50% 50%" };
  }

  const main = images && typeof images === "object" && !Array.isArray(images)
    ? (images as { main?: { widths?: Record<string, string>; aspect?: number; focal?: { x: number; y: number } } }).main
    : undefined;

  const widths = main?.widths
    ? Object.entries(main.widths)
        .map(([w, url]) => [Number(w), url] as const)
        .filter(([w, url]) => w > 0 && typeof url === "string")
        .sort((a, b) => a[0] - b[0])
    : [];

  if (widths.length) {
    const src = (widths.filter(([w]) => w <= 640).pop() ?? widths[0])[1];
    const fx = Math.round((main?.focal?.x ?? 0.5) * 100);
    const fy = Math.round((main?.focal?.y ?? 0.5) * 100);
    return {
      src,
      srcSet: widths.map(([w, url]) => `${url} ${w}w`).join(", "),
      objectPosition: `${fx}% ${fy}%`,
      aspect: main?.aspect,
    };
  }

  const url = safeImageUrl(fallbackUrl);
  return url ? { src: url, objectPosition: "50% 50%" } : null;
}

// ── Compact main image (for list payloads) ─────────────────────────────
//
// Category pages ship every item to the client for instant filtering, so
// the full images.main object (4 URLs) is too heavy per row. The compact
// form carries widths + version + focal point (~60 bytes); URLs are
// rebuilt from the deterministic storage path written by storeMainImage().

export interface CompactMainImage {
  id: string;
  w: number[];
  v: string;
  fx: number;
  fy: number;
}

export function compactMainImage(itemId: string, images: unknown): CompactMainImage | null {
  // Admin-picked gallery cover wins → let the caller's cover_url render.
  if (extractGalleryImages(images).some((g) => g.isDefault)) return null;
  const main = images && typeof images === "object" && !Array.isArray(images)
    ? (images as { main?: { widths?: Record<string, string>; focal?: { x: number; y: number } } }).main
    : undefined;
  if (!main?.widths) return null;
  const w = Object.keys(main.widths).map(Number).filter((n) => n > 0).sort((a, b) => a - b);
  if (!w.length) return null;
  const ref = main.widths[String(w.filter((n) => n <= 640).pop() ?? w[0])] ?? "";
  const v = /[?&]v=([^&]+)/.exec(ref)?.[1] ?? "";
  return { id: itemId, w, v, fx: main.focal?.x ?? 0.5, fy: main.focal?.y ?? 0.5 };
}

function isCompact(x: unknown): x is CompactMainImage {
  return !!x && typeof x === "object" && Array.isArray((x as CompactMainImage).w) && typeof (x as CompactMainImage).id === "string";
}

function expandCompact(c: CompactMainImage): MainImageSource {
  const base = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/media/items/${c.id}/main-`;
  const url = (w: number) => `${base}${w}.webp${c.v ? `?v=${c.v}` : ""}`;
  const src = url(c.w.filter((n) => n <= 640).pop() ?? c.w[0]);
  return {
    src,
    srcSet: c.w.map((w) => `${url(w)} ${w}w`).join(", "),
    objectPosition: `${Math.round(c.fx * 100)}% ${Math.round(c.fy * 100)}%`,
  };
}

/** mainImageSource() for either the full images jsonb or a CompactMainImage. */
export function anyImageSource(images: unknown, fallbackUrl?: string | null): MainImageSource | null {
  return isCompact(images) ? expandCompact(images) : mainImageSource(images, fallbackUrl);
}
